// @name Pixel art
// @background #1a1c2c
// @refresh 3600
// A pixel art editor for a touch screen: a 16x16, 24x24 or 32x32 grid, a
// palette of 16 colors, a pen, a fill bucket, an eraser, a color picker,
// mirror drawing, undo and redo. Pictures are saved as SVG files in the
// assets folder ("Pixel art" by default): a rect per run of pixels, so they
// open anywhere, with the grid itself in a data- attribute so they open
// here again exactly. In high contrast the palette is black, white and a
// dither of the two.
//
// How it draws: the grid is a canvas (frameos.canvas). A painted cell is
// one small rect drawn into it, and the frame repaints only that; the whole
// grid is drawn again only when the canvas is new, a picture is opened or
// the look changes (a path per color, not a rect per cell).
import { Icon, ICONS, Sheet, SheetBar, Action, FileRow, NameForm, setZoom, z } from './ui'
import { safeName, safeFolder, listFiles, writeText, readText, svgRoot, svgElements, svgTitle, hexColor, xml, baseName, stripExt } from './files'

const PALETTES = {
  sweetie16: ['#1a1c2c', '#5d275d', '#b13e53', '#ef7d57', '#ffcd75', '#a7f070', '#38b764', '#257179', '#29366f', '#3b5dc9', '#41a6f6', '#73eff7', '#f4f4f4', '#94b0c2', '#566c86', '#333c57'],
  pico8: ['#000000', '#1d2b53', '#7e2553', '#008751', '#ab5236', '#5f574f', '#c2c3c7', '#fff1e8', '#ff004d', '#ffa300', '#ffec27', '#00e436', '#29adff', '#83769c', '#ff77a8', '#ffccaa'],
  calm: ['#1f2937', '#334155', '#64748b', '#cbd5e1', '#f8fafc', '#7f1d1d', '#c2410c', '#d97706', '#facc15', '#3f6212', '#15803d', '#0f766e', '#0369a1', '#1e3a8a', '#6b21a8', '#be185d'],
}
const SIZES = [16, 24, 32]
const HEX = '0123456789abcdef'
const EMPTY = '.'

const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

const THEMES = {
  color: {
    page: 'bg-[#1a1c2c] text-slate-100',
    well: '#262b44',
    empty: ['#d9dde5', '#c6ccd7'],
    gridLine: '#000000',
    gridOpacity: 0.22,
    tool: 'bg-white/10 text-slate-100 active:bg-white/20',
    toolOn: 'bg-[#ffcd75] text-[#1a1c2c]',
    toolOff: 'bg-white/5 text-slate-500',
    swatch: 'border-2 border-white/10',
    swatchOn: 'border-4 border-[#ffcd75]',
    label: 'text-slate-400',
    cover: 'bg-black/50',
    sheet: 'bg-[#f4f4f4] text-[#1a1c2c]',
    bar: 'bg-[#94b0c2]/40',
    ghost: 'active:bg-black/10',
    muted: 'text-[#566c86]',
    button: 'bg-white text-[#1a1c2c] active:bg-slate-200',
    primary: 'bg-[#29366f] text-white active:bg-[#3b5dc9]',
    danger: 'bg-[#b13e53] text-white',
    row: 'bg-white active:bg-slate-100',
    field: 'bg-white',
    accentText: 'text-[#3b5dc9]',
    chip: 'bg-white text-[#1a1c2c] border-2 border-slate-300',
    chipOn: 'bg-[#29366f] text-white border-2 border-[#29366f]',
    note: 'bg-[#f4f4f4] text-[#1a1c2c]',
  },
  high: {
    page: 'bg-white text-black',
    well: '#ffffff',
    empty: ['#ffffff', '#ffffff'],
    gridLine: '#000000',
    gridOpacity: 1,
    tool: 'bg-white text-black border-2 border-black',
    toolOn: 'bg-black text-white border-2 border-black',
    toolOff: 'bg-white text-black border-2 border-black',
    swatch: 'border-2 border-black',
    swatchOn: 'border-[6px] border-black',
    label: 'text-black',
    cover: '',
    sheet: 'bg-white text-black border-4 border-black',
    bar: 'bg-white border-b-2 border-black',
    ghost: '',
    muted: 'text-black',
    button: 'bg-white text-black border-2 border-black',
    primary: 'bg-black text-white',
    danger: 'bg-black text-white',
    row: 'bg-white border-2 border-black',
    field: 'bg-white border-2 border-black',
    accentText: 'text-black',
    chip: 'bg-white text-black border-2 border-black',
    chipOn: 'bg-black text-white border-2 border-black',
    note: 'bg-black text-white',
  },
}

// ------------------------------------------------------------------ state

// The picture (`art`, private, on disk): its file name, grid size, and the
// cells as one string, a character each, row by row: "." empty, "0".."f" a
// color of the palette. Small (1 KB at 32x32) and simple to undo.
let art = null
const blank = (n) => ({ name: '', n, cells: EMPTY.repeat(n * n), rev: 0, saved: 0, gen: 0 })
const loadArt = (app, n) => {
  const kept = app.state.art
  if (kept && typeof kept === 'object' && SIZES.includes(kept.n) && typeof kept.cells === 'string' && kept.cells.length === kept.n * kept.n) return kept
  return blank(n)
}
const commit = () => frameos.setState('art', art)

let ui = null
const UI_DEFAULTS = { tool: 'pen', color: 0, mirror: false, panel: '', draft: '', asking: '', note: '', size: 0 }
const loadUi = () => Object.assign({}, UI_DEFAULTS, frameos.recall('ui') || {})
const setUi = (patch) => {
  Object.assign(ui, patch)
  frameos.remember('ui', ui)
}
const note = (text) => setUi({ note: text })

// What a tap on the grid, a tool or a swatch changes, as signals: such a tap
// runs only the components that read them, not get().
const toolOn = { pen: signal(false), fill: signal(false), eraser: signal(false), picker: signal(false) }
const mirrorOn = signal(false)
const chosen = Array.from({ length: 16 }, () => signal(false))
const canUndo = signal(false)
const canRedo = signal(false)
const dirty = signal(false)
const statusLine = signal('')
const inked = signal(0) // the grid's draws so far: the canvas changed
let draws = 0
const show = () => {
  for (const id in toolOn) toolOn[id].value = ui.tool === id
  mirrorOn.value = ui.mirror
  chosen.forEach((on, i) => {
    on.value = ui.color === i
  })
  canUndo.value = (frameos.recall('undo') || []).length > 0
  canRedo.value = (frameos.recall('redo') || []).length > 0
  dirty.value = art.rev !== art.saved && art.cells !== EMPTY.repeat(art.n * art.n)
  const colorName = hc ? ['Black', 'White', 'Dither'][ui.color] : palette[ui.color]
  statusLine.value = `${art.name || 'Untitled'} · ${art.n}x${art.n}${ui.mirror ? ' · mirror' : ''} · ${colorName}`
  inked.value = draws
}
// A handler that changed only what the signals show sets them; one that
// opened a sheet or a note or another picture sets none, so get() runs.
const others = () => [ui.panel, ui.note, ui.asking, ui.draft, ui.size, art.name, art.n, art.gen].join('|')
const tap = (handler) => (e) => {
  const before = others()
  handler(e)
  if (others() === before) show()
}

let palette = PALETTES.sweetie16
let folder = 'Pixel art'
let hc = false
let showGrid = true
let T = THEMES.color

// The palette's darkest and lightest colors: high contrast paints with them.
const darkest = () => lightOrder()[0]
const lightest = () => lightOrder()[15]
const luma = (hex) => {
  const v = parseInt(hex.slice(1), 16)
  return (0.299 * ((v >> 16) & 255) + 0.587 * ((v >> 8) & 255) + 0.114 * (v & 255)) / 255
}
const lightOrder = () => palette.map((c, i) => [luma(c), i]).sort((a, b) => a[0] - b[0]).map((p) => p[1])

// ----------------------------------------------------------------- canvas

let canvas = null
let S = 320 // the grid's size in the UI's pixels
let k = 1 // canvas pixels per UI pixel
let cell = 20 // a cell in canvas pixels

// What a cell looks like: [fill] or, for a mid tone in high contrast, a
// 2x2 dither of black and white.
const cellLook = (ch, x, y) => {
  if (ch === EMPTY) return hc ? '#ffffff' : T.empty[(x + y) % 2]
  const color = palette[HEX.indexOf(ch)] || '#000000'
  if (!hc) return color
  const l = luma(color)
  return l < 0.3 ? '#000000' : l > 0.7 ? '#ffffff' : 'dither'
}

// Rect paths by look: {fill: "M x y h c v c h -c z..."}.
const addCell = (paths, x, y, ch) => {
  const look = cellLook(ch, x, y)
  const px = x * cell
  const py = y * cell
  if (look === 'dither') {
    const h = cell / 2
    paths['#000000'] = (paths['#000000'] || '') + `M${px} ${py}h${h}v${h}h${-h}zM${px + h} ${py + h}h${h}v${h}h${-h}z`
    paths['#ffffff'] = (paths['#ffffff'] || '') + `M${px + h} ${py}h${h}v${h}h${-h}zM${px} ${py + h}h${h}v${h}h${-h}z`
  } else {
    paths[look] = (paths[look] || '') + `M${px} ${py}h${cell}v${cell}h${-cell}z`
  }
}
// Each cell owns the grid line along its top and its left, and a cell of the
// last row or column the closing line along its bottom or right as well.
const gridPath = (cells) => cells.map(([x, y]) => `M${x * cell} ${y * cell + 0.5}h${cell}M${x * cell + 0.5} ${y * cell}v${cell}`).join('')
const edgePath = (cells) => {
  const end = art.n * cell - 0.5
  return cells.map(([x, y]) => (y === art.n - 1 ? `M${x * cell} ${end}h${cell}` : '') + (x === art.n - 1 ? `M${end} ${y * cell}v${cell}` : '')).join('')
}
const CellsEl = ({ cells }) => {
  const paths = {}
  for (const [x, y, ch] of cells) addCell(paths, x, y, ch)
  return (
    <g>
      {Object.keys(paths).map((fill) => <path d={paths[fill]} fill={fill} />)}
      {showGrid ? <path d={gridPath(cells)} fill="none" stroke={T.gridLine} strokeOpacity={T.gridOpacity} strokeWidth={1} /> : null}
      {showGrid && edgePath(cells) ? <path d={edgePath(cells)} fill="none" stroke={T.gridLine} strokeOpacity={T.gridOpacity} strokeWidth={1} /> : null}
    </g>
  )
}

const paintAll = () => {
  const n = art.n
  frameos.clear(canvas, T.well)
  // A row at a time keeps each draw's path short.
  for (let y = 0; y < n; y++) {
    const cells = []
    for (let x = 0; x < n; x++) cells.push([x, y, art.cells[y * n + x]])
    frameos.draw(canvas, <CellsEl cells={cells} />)
  }
}

// ---------------------------------------------------------------- editing

const setCells = (changes) => {
  // changes: [[x, y, ch]]; the string rebuilt once, the cells drawn once.
  if (!changes.length) return
  const chars = art.cells.split('')
  const drawn = []
  for (const [x, y, ch] of changes) {
    const i = y * art.n + x
    if (chars[i] === ch) continue
    chars[i] = ch
    drawn.push([x, y, ch])
  }
  if (!drawn.length) return
  art.cells = chars.join('')
  if (canvas) {
    frameos.draw(canvas, <CellsEl cells={drawn} />)
    draws++
  }
  // In state at once: the render after this handler reads the picture there.
  commit()
}

// What the pen puts in a cell: the color, or in high contrast the darkest
// or lightest color, or for the dither a checker of the two.
const inkAt = (x, y) => {
  if (ui.tool === 'eraser') return EMPTY
  if (hc) {
    if (ui.color === 2) return HEX[(x + y) % 2 ? lightest() : darkest()]
    return HEX[ui.color === 1 ? lightest() : darkest()]
  }
  return HEX[ui.color]
}
const withMirror = (x, y) => {
  const out = [[x, y, inkAt(x, y)]]
  const mx = art.n - 1 - x
  if (ui.mirror && mx !== x) out.push([mx, y, inkAt(mx, y)])
  return out
}

const snapshot = () => {
  const undo = frameos.recall('undo') || []
  undo.push(art.cells)
  frameos.remember('undo', undo.slice(-30))
  frameos.remember('redo', [])
}
const swap = (from, to) => {
  const stack = frameos.recall(from) || []
  const cells = stack.pop()
  if (cells === undefined) return
  const other = frameos.recall(to) || []
  other.push(art.cells)
  frameos.remember(to, other.slice(-30))
  frameos.remember(from, stack)
  const changes = []
  for (let i = 0; i < cells.length; i++) if (cells[i] !== art.cells[i]) changes.push([i % art.n, Math.floor(i / art.n), cells[i]])
  setCells(changes)
  art.rev = (art.rev || 0) + 1
  commit()
}
const undo = () => swap('undo', 'redo')
const redo = () => swap('redo', 'undo')

// 4-connected flood fill from (x, y) with what the pen puts there.
const fill = (x, y) => {
  const n = art.n
  const target = art.cells[y * n + x]
  const seen = new Uint8Array(n * n)
  const stack = [y * n + x]
  const changes = []
  while (stack.length) {
    const i = stack.pop()
    if (seen[i] || art.cells[i] !== target) continue
    seen[i] = 1
    const cx = i % n
    const cy = (i - cx) / n
    changes.push([cx, cy, inkAt(cx, cy)])
    if (cx > 0) stack.push(i - 1)
    if (cx < n - 1) stack.push(i + 1)
    if (cy > 0) stack.push(i - n)
    if (cy < n - 1) stack.push(i + n)
  }
  setCells(changes)
}

// The cell under a pointer, or null off the grid.
const cellAt = (e) => {
  const size = S / art.n
  const x = Math.floor(e.localX / size)
  const y = Math.floor(e.localY / size)
  return x >= 0 && y >= 0 && x < art.n && y < art.n ? [x, y] : null
}
// The last cell a drag painted, so a quick move paints the cells between.
const lastCell = () => frameos.recall('last') || null

const press = (e) => {
  if (ui.panel || ui.note) {
    const had = ui.panel
    setUi({ panel: '', note: '' })
    if (had) return
  }
  const at = cellAt(e)
  if (!at) return
  const [x, y] = at
  if (ui.tool === 'picker') {
    const ch = art.cells[y * art.n + x]
    if (ch !== EMPTY) {
      const i = HEX.indexOf(ch)
      setUi({ color: hc ? (luma(palette[i]) < 0.3 ? 0 : luma(palette[i]) > 0.7 ? 1 : 2) : i, tool: 'pen' })
    }
    return
  }
  snapshot()
  if (ui.tool === 'fill') {
    fill(x, y)
    if (ui.mirror && art.n - 1 - x !== x) fill(art.n - 1 - x, y)
    art.rev = (art.rev || 0) + 1
    commit()
    return
  }
  setCells(withMirror(x, y))
  frameos.remember('last', [x, y])
}
const drag = (e) => {
  const last = lastCell()
  if (!last || (ui.tool !== 'pen' && ui.tool !== 'eraser')) return
  const at = cellAt(e)
  if (!at) return
  const [x1, y1] = at
  let [x0, y0] = last
  if (x0 === x1 && y0 === y1) return
  // Every cell on the line from the last one (Bresenham).
  const changes = []
  const dx = Math.abs(x1 - x0)
  const dy = -Math.abs(y1 - y0)
  const sx = x0 < x1 ? 1 : -1
  const sy = y0 < y1 ? 1 : -1
  let err = dx + dy
  for (let guard = 0; guard < 200; guard++) {
    for (const c of withMirror(x0, y0)) changes.push(c)
    if (x0 === x1 && y0 === y1) break
    const e2 = 2 * err
    if (e2 >= dy) {
      err += dy
      x0 += sx
    }
    if (e2 <= dx) {
      err += dx
      y0 += sy
    }
  }
  setCells(changes)
  frameos.remember('last', [x1, y1])
}
const lift = () => {
  if (!lastCell()) return
  frameos.remember('last', null)
  art.rev = (art.rev || 0) + 1
  commit()
}
// A pointer on the grid redraws the grid alone, painted or not: its one
// <img> again costs less than the get() a handler that sets no signal runs.
const onGrid = (handler) => tap((e) => {
  handler(e)
  draws++
})
const onPress = onGrid(press)
const onDrag = onGrid(drag)
const onLift = onGrid(lift)

// ------------------------------------------------------------------ files

const pathOf = (name) => `${folder}/${name}.svg`

// The picture as an SVG file: a rect per run of one color in a row, at 16
// pixels a cell, crisp edges; the grid and the palette in data- attributes.
const svgText = (name) => {
  const n = art.n
  const scale = 16
  const out = [
    `<svg xmlns="http://www.w3.org/2000/svg" width="${n * scale}" height="${n * scale}" viewBox="0 0 ${n} ${n}" shape-rendering="crispEdges"` +
      ` data-frameos="pixel-art" data-grid="${n}" data-palette="${palette.join(',')}" data-pixels="${art.cells}">`,
    `<title>${xml(name)}</title>`,
    `<desc>Pixel art from FrameOS, ${n}x${n}.</desc>`,
  ]
  for (let y = 0; y < n; y++) {
    let x = 0
    while (x < n) {
      const ch = art.cells[y * n + x]
      let run = 1
      while (x + run < n && art.cells[y * n + x + run] === ch) run++
      if (ch !== EMPTY) out.push(`<rect x="${x}" y="${y}" width="${run}" height="1" fill="${palette[HEX.indexOf(ch)]}"/>`)
      x += run
    }
  }
  out.push('</svg>')
  return out.join('\n') + '\n'
}

const nearest = (hex) => {
  const v = parseInt(hex.slice(1), 16)
  let best = 0
  let bestD = Infinity
  palette.forEach((c, i) => {
    const w = parseInt(c.slice(1), 16)
    const d = (((v >> 16) & 255) - ((w >> 16) & 255)) ** 2 + (((v >> 8) & 255) - ((w >> 8) & 255)) ** 2 + ((v & 255) - (w & 255)) ** 2
    if (d < bestD) {
      bestD = d
      best = i
    }
  })
  return HEX[best]
}

// A file back into cells: ours from data-pixels (colors matched to this
// palette), anyone else's from its rects, a cell the size of the smallest.
const parseArt = (text) => {
  const root = svgRoot(text || '')
  if (!root) return null
  const n = parseInt(root.attrs['data-grid'])
  const pixels = root.attrs['data-pixels'] || ''
  if (SIZES.includes(n) && pixels.length === n * n) {
    const theirs = (root.attrs['data-palette'] || '').split(',').map(hexColor)
    const map = {}
    let cells = ''
    for (const ch of pixels) {
      if (ch === EMPTY || HEX.indexOf(ch) < 0) {
        cells += EMPTY
        continue
      }
      if (!(ch in map)) map[ch] = theirs[HEX.indexOf(ch)] ? nearest(theirs[HEX.indexOf(ch)]) : ch
      cells += map[ch]
    }
    return { n, cells }
  }
  const rects = svgElements(text, ['rect']).map(([, a]) => ({
    x: parseFloat(a.x || '0') - root.x, y: parseFloat(a.y || '0') - root.y,
    w: parseFloat(a.width), h: parseFloat(a.height), fill: hexColor(a.fill),
  })).filter((r) => r.w > 0 && r.h > 0 && r.fill && !(r.w >= root.w && r.h >= root.h))
  if (!rects.length) return null
  const unitSize = Math.min(...rects.map((r) => Math.min(r.w, r.h)))
  const across = Math.round(Math.max(root.w, root.h) / unitSize)
  const size = SIZES.find((s) => s >= across) || 32
  const chars = EMPTY.repeat(size * size).split('')
  for (const r of rects) {
    const ch = nearest(r.fill)
    for (let y = Math.round(r.y / unitSize); y < Math.round((r.y + r.h) / unitSize); y++) {
      for (let x = Math.round(r.x / unitSize); x < Math.round((r.x + r.w) / unitSize); x++) {
        if (x >= 0 && y >= 0 && x < size && y < size) chars[y * size + x] = ch
      }
    }
  }
  return { n: size, cells: chars.join('') }
}

const save = (name) => {
  if (!writeText(pathOf(name), svgText(name))) {
    note('Could not save: does the scene have the "writes assets folder" permission?')
    return false
  }
  art.name = name
  art.saved = art.rev
  commit()
  note(`Saved ${pathOf(name)}`)
  return true
}
const replaced = (next) => {
  next.gen = (Number(art.gen) || 0) + 1
  art = next
  frameos.remember('undo', [])
  frameos.remember('redo', [])
  commit()
}
const open = (path) => {
  const parsed = parseArt(readText(path))
  if (!parsed) {
    note(`${baseName(path)} has no pixels this can read`)
    return
  }
  replaced({ name: stripExt(baseName(path)), n: parsed.n, cells: parsed.cells, rev: 0, saved: 0 })
  setUi({ panel: '', asking: '', note: `Opened ${baseName(path)}` })
}
const freshName = () => {
  const taken = listFiles(folder, ['.svg']).map((p) => stripExt(baseName(p)).toLowerCase())
  for (let i = 1; ; i++) if (!taken.includes(`pixels ${i}`)) return `Pixels ${i}`
}

// ----------------------------------------------------------------- pieces

const TOOLS = [
  ['pen', 'Pen', ICONS.pencil],
  ['fill', 'Fill', ICONS.bucket],
  ['eraser', 'Eraser', ICONS.eraser],
  ['picker', 'Pick', ICONS.picker],
]

const Button = ({ b, d, on, off, label, onClick }) => (
  <div className={`flex flex-col items-center justify-center w-[${b}px] h-[${b}px] shrink-0 rounded-[${z(12)}px] ${on ? T.toolOn : off ? T.toolOff : T.tool}`}
    onClick={onClick}>
    <Icon d={d} className={`w-[${Math.round(b * 0.42)}px] h-[${Math.round(b * 0.42)}px]`} />
    {label && b >= 52 ? <span className={`text-[${Math.max(10, Math.round(b * 0.19))}px] font-semibold`}>{label}</span> : null}
  </div>
)

// Each button reads its own signal: a tap redraws the buttons it changed.
const ToolButton = memo(({ b, id, label, d, hcLook }) => (
  <Button b={b} d={d} label={label} on={toolOn[id].value} onClick={tap(() => setUi({ tool: id, panel: '' }))} />
))
const MirrorButton = memo(({ b, hcLook }) => (
  <Button b={b} d={ICONS.mirror} label="Mirror" on={mirrorOn.value} onClick={tap(() => setUi({ mirror: !ui.mirror }))} />
))
const UndoButton = memo(({ b, hcLook }) => <Button b={b} d={ICONS.undo} label="Undo" off={!canUndo.value} onClick={tap(undo)} />)
const RedoButton = memo(({ b, hcLook }) => <Button b={b} d={ICONS.redo} label="Redo" off={!canRedo.value} onClick={tap(redo)} />)
const FileButton = memo(({ b, hcLook }) => (
  <Button b={b} d={ICONS.menu} label={dirty.value ? 'File •' : 'File'} onClick={() => setUi({ panel: 'menu', asking: '' })} />
))

// Not memo()'d itself: a memo()'d component taken back whole would keep its
// buttons from being drawn again alone.
const Tools = ({ b, cols, hcLook }) => (
  <div className={`grid grid-cols-${cols} gap-[${z(6)}px]`}>
    {TOOLS.map(([id, label, d]) => <ToolButton b={b} id={id} label={label} d={d} hcLook={hcLook} />)}
    <MirrorButton b={b} hcLook={hcLook} />
    <UndoButton b={b} hcLook={hcLook} />
    <RedoButton b={b} hcLook={hcLook} />
    <FileButton b={b} hcLook={hcLook} />
  </div>
)

const pickColor = (i) => setUi({ color: i, tool: ui.tool === 'eraser' || ui.tool === 'picker' ? 'pen' : ui.tool })

const Swatch = memo(({ sw, color, i, label, hcLook }) => (
  <div className={`w-[${sw}px] h-[${sw}px] shrink-0 flex items-center justify-center rounded-[${z(8)}px] ${chosen[i].value ? T.swatchOn : T.swatch} bg-[${color}]`}
    onClick={tap(() => pickColor(i))}>
    {label ? <span className={`text-[${z(12)}px] font-bold ${color === '#000000' ? 'text-white' : 'text-black'}`}>{label}</span> : null}
  </div>
))

// High contrast: black, white and a checker of the two.
const DitherSwatch = memo(({ sw }) => (
  <div className={`w-[${sw}px] h-[${sw}px] shrink-0 rounded-[${z(8)}px] overflow-hidden ${chosen[2].value ? T.swatchOn : T.swatch}`}
    onClick={tap(() => pickColor(2))}>
    <svg className="w-full h-full" viewBox="0 0 8 8" preserveAspectRatio="none">
      <rect width="8" height="8" fill="#ffffff" />
      <path d="M0 0h2v2H0zM4 0h2v2H4zM2 2h2v2H2zM6 2h2v2H6zM0 4h2v2H0zM4 4h2v2H4zM2 6h2v2H2zM6 6h2v2H6z" fill="#000000" />
    </svg>
  </div>
))

const Palette = ({ sw, cols }) => (
  <div className={`grid grid-cols-${cols} gap-[${z(6)}px]`}>
    {hc ? (
      [
        <Swatch sw={sw} color="#000000" i={0} hcLook={hc} />,
        <Swatch sw={sw} color="#ffffff" i={1} hcLook={hc} />,
        <DitherSwatch sw={sw} />,
      ]
    ) : palette.map((color, i) => <Swatch sw={sw} color={color} i={i} hcLook={hc} />)}
  </div>
)

// The line under the tools: the picture, the grid, mirror and the color.
const Status = memo(({ size, hcLook }) => <span className={`text-[${size}px] truncate ${T.label}`}>{statusLine.value}</span>)

// The grid, drawn again in place when a tap painted into its canvas.
const Grid = memo(({ S, src }) => {
  inked.value
  return <img className={`w-[${S}px] h-[${S}px] shrink-0`} src={src} onPointerDown={onPress} onPointerMove={onDrag} onPointerUp={onLift} />
})

// ----------------------------------------------------------------- sheets

const SizeChips = ({ value, onPick }) => (
  <div className={`grid grid-cols-3 gap-[${z(8)}px]`}>
    {SIZES.map((size) => (
      <div className={`flex items-center justify-center h-[${z(52)}px] rounded-[${z(12)}px] text-[${z(16)}px] ${value === size ? T.chipOn : T.chip}`}
        onClick={() => onPick(size)}>{`${size} x ${size}`}</div>
    ))}
  </div>
)

const MenuSheet = ({ w, gridSetting }) => {
  const close = () => setUi({ panel: '', asking: '' })
  const empty = art.cells === EMPTY.repeat(art.n * art.n)
  const dirty = art.rev !== art.saved && !empty
  if (ui.asking === 'new') {
    const size = ui.size || gridSetting
    return (
      <Sheet t={T} w={w} onClose={close}>
        <SheetBar t={T} title="A new picture" sub={dirty ? 'The changes since it was last saved are lost' : 'Saved files stay'} onClose={close} />
        <div className={`flex flex-col gap-[${z(12)}px] p-[${z(16)}px]`}>
          <SizeChips value={size} onPick={(pick) => setUi({ size: pick })} />
          <Action t={T} kind="primary" d={ICONS.plus} label={`New ${size} x ${size} picture`} onClick={() => {
            replaced(blank(size))
            setUi({ panel: '', asking: '', note: 'A new picture' })
          }} />
        </div>
      </Sheet>
    )
  }
  if (ui.asking === 'clear') {
    return (
      <Sheet t={T} w={w} onClose={close}>
        <SheetBar t={T} title="Clear every pixel?" sub="Undo brings them back" onClose={close} />
        <div className={`flex gap-[${z(12)}px] p-[${z(16)}px]`}>
          <div className="flex-1"><Action t={T} label="Cancel" onClick={() => setUi({ asking: '' })} /></div>
          <div className="flex-1"><Action t={T} kind="danger" d={ICONS.broom} label="Clear" onClick={() => {
            snapshot()
            const changes = []
            for (let i = 0; i < art.cells.length; i++) if (art.cells[i] !== EMPTY) changes.push([i % art.n, Math.floor(i / art.n), EMPTY])
            setCells(changes)
            art.rev = (art.rev || 0) + 1
            commit()
            setUi({ panel: '', asking: '' })
          }} /></div>
        </div>
      </Sheet>
    )
  }
  return (
    <Sheet t={T} w={w} onClose={close}>
      <SheetBar t={T} title={art.name || 'Untitled picture'}
        sub={`${art.n} x ${art.n} · ${art.name ? `${pathOf(art.name)}${dirty ? ' · changes not saved' : ''}` : empty ? 'empty' : 'not saved yet'}`} onClose={close} />
      <div className={`grid grid-cols-2 gap-[${z(12)}px] p-[${z(16)}px]`}>
        <Action t={T} kind="primary" d={ICONS.save} label="Save" onClick={() => {
          if (art.name) {
            if (save(art.name)) setUi({ panel: '' })
          } else setUi({ panel: 'save', draft: freshName(), asking: '' })
        }} />
        <Action t={T} d={ICONS.file} label="Save as…" onClick={() => setUi({ panel: 'save', draft: art.name || freshName(), asking: '' })} />
        <Action t={T} d={ICONS.folder} label="Open…" onClick={() => setUi({ panel: 'open', asking: '' })} />
        <Action t={T} d={ICONS.plus} label="New…" onClick={() => setUi({ asking: 'new', size: art.n })} />
        <Action t={T} d={ICONS.broom} label="Clear…" onClick={() => setUi({ asking: empty ? '' : 'clear' })} />
      </div>
      {ui.note ? <div className={`mx-[${z(16)}px] mb-[${z(16)}px] px-[${z(16)}px] py-[${z(8)}px] rounded-[${z(12)}px] text-[${z(16)}px] ${T.button}`}>{ui.note}</div> : null}
    </Sheet>
  )
}

const OpenSheet = ({ w, h }) => {
  const files = listFiles(folder, ['.svg'])
  const close = () => setUi({ panel: '', asking: '' })
  return (
    <Sheet t={T} w={w} h={h} onClose={close}>
      <SheetBar t={T} title="Open a picture" sub={`${folder}/ · ${files.length} ${files.length === 1 ? 'file' : 'files'}`}
        onBack={() => setUi({ panel: 'menu', asking: '' })} onClose={close} />
      <div className={`flex-1 overflow-y-auto p-[${z(12)}px]`}>
        <div className={`flex flex-col gap-[${z(8)}px]`}>
          {files.length === 0 ? <span className={`p-[${z(12)}px] text-[${z(18)}px] ${T.muted}`}>{`Nothing saved in ${folder} yet.`}</span> : null}
          {files.map((path) => {
            const name = stripExt(baseName(path))
            return (
              <FileRow t={T} d={ICONS.image} name={name} sub={name === art.name ? 'Open now' : ''} asking={ui.asking === path}
                onOpen={() => open(path)} onAsk={() => setUi({ asking: path })} onCancel={() => setUi({ asking: '' })}
                onDelete={() => {
                  frameos.deleteAsset(path)
                  if (name === art.name) {
                    art.name = ''
                    commit()
                  }
                  setUi({ asking: '', note: `Deleted ${baseName(path)}` })
                }} />
            )
          })}
        </div>
      </div>
    </Sheet>
  )
}

const SaveSheet = ({ w }) => {
  const close = () => setUi({ panel: '', asking: '' })
  const name = safeName(ui.draft)
  const trySave = (replace) => {
    if (!name) {
      note('Give it a name first')
      return
    }
    if (!replace && name !== art.name && frameos.assetExists(pathOf(name))) {
      setUi({ asking: 'replace' })
      return
    }
    if (save(name)) setUi({ panel: '', asking: '' })
  }
  return (
    <Sheet t={T} w={w} onClose={close}>
      <SheetBar t={T} title="Save the picture" sub={`as an SVG file in ${folder}/`} onBack={() => setUi({ panel: 'menu', asking: '' })} onClose={close} />
      <div className={`flex flex-col gap-[${z(12)}px] p-[${z(16)}px]`}>
        {ui.asking === 'replace' ? (
          <div className={`flex flex-col gap-[${z(12)}px]`}>
            <span className={`text-[${z(18)}px]`}>{`"${name}" is there already. Replace it?`}</span>
            <div className={`flex gap-[${z(12)}px]`}>
              <div className="flex-1"><Action t={T} label="Cancel" onClick={() => setUi({ asking: '' })} /></div>
              <div className="flex-1"><Action t={T} kind="danger" label="Replace" onClick={() => trySave(true)} /></div>
            </div>
          </div>
        ) : (
          <NameForm t={T} value={ui.draft} placeholder="Name" label="Save" onChange={(v) => setUi({ draft: v, note: '' })} onSave={() => trySave(false)} />
        )}
        {ui.note ? <span className={`text-[${z(16)}px] ${T.muted}`}>{ui.note}</span> : null}
      </div>
    </Sheet>
  )
}

// -------------------------------------------------------------------- get

export function get(app, context) {
  const W = Math.round(context.imageWidth ?? app.frame.width)
  const H = Math.round(context.imageHeight ?? app.frame.height)
  hc = highContrast(app)
  T = hc ? THEMES.high : THEMES.color
  setZoom(Math.max(1, Math.min(2, Math.min(W, H) / 480)))
  palette = PALETTES[app.state.palette] || PALETTES.sweetie16
  folder = safeFolder(app.state.folder, 'Pixel art')
  showGrid = app.state.gridLines !== 'false' && app.state.gridLines !== false
  const gridSetting = SIZES.includes(parseInt(app.state.grid)) ? parseInt(app.state.grid) : 16
  art = loadArt(app, gridSetting)
  // An empty picture follows the grid setting.
  if (art.n !== gridSetting && art.cells === EMPTY.repeat(art.n * art.n)) art = blank(gridSetting)
  ui = loadUi()
  if (ui.color >= (hc ? 3 : 16)) ui.color = 0

  // Where things go: the grid is a square as large as fits beside the tools
  // (wide), above them (tall), or with the palette beside it and the tools
  // under it (square).
  const pad = z(12)
  const gap = z(12)
  const ratio = W / H
  const layout = ratio >= 1.3 ? 'wide' : ratio <= 1 / 1.3 ? 'tall' : 'square'
  const swatches = hc ? 3 : 16
  let b = z(56)
  let sw = z(44)
  let toolCols = 4
  let palCols = 4
  if (layout === 'wide') {
    S = H - 2 * pad
    const side = W - S - 2 * pad - gap
    b = Math.max(44, Math.min(z(76), Math.floor((side - 3 * z(6)) / 4)))
    const rowsLeft = H - 2 * pad - 2 * b - z(6) - gap - z(20)
    sw = Math.max(32, Math.min(Math.floor((side - 3 * z(6)) / 4), Math.floor((rowsLeft - 3 * z(6)) / 4)))
  } else if (layout === 'tall') {
    // Tools in two rows of four under the palette's two rows of eight.
    palCols = hc ? 3 : 8
    b = Math.max(44, Math.min(z(72), Math.floor((W - 2 * pad - 3 * z(6)) / 4)))
    sw = Math.max(32, Math.min(z(52), Math.floor((W - 2 * pad - 7 * z(6)) / 8)))
    const palRows = hc ? 1 : 2
    S = Math.min(W - 2 * pad, H - 2 * pad - 3 * gap - 2 * b - z(6) - palRows * sw - (palRows - 1) * z(6) - z(20))
  } else {
    toolCols = 8
    palCols = hc ? 1 : 2
    b = Math.max(44, Math.floor((W - 2 * pad - 7 * z(6)) / 8))
    b = Math.min(b, z(56))
    const rows = Math.ceil(swatches / palCols)
    S = Math.min(H - 2 * pad - gap - b, W - 2 * pad - gap - palCols * 40 - (palCols - 1) * z(6))
    sw = Math.max(32, Math.min(z(52), Math.floor((S - (rows - 1) * z(6)) / rows)))
    S = Math.min(H - 2 * pad - gap - b, W - 2 * pad - gap - palCols * sw - (palCols - 1) * z(6))
  }
  // A round panel: the grid in the middle, the tools on pads along the top
  // and bottom of the rim, the palette along its left and right.
  const round = context.round === true
  const R = Math.min(W, H) / 2 - 12
  if (round) {
    b = Math.max(40, Math.round(R * 0.2))
    sw = Math.max(26, Math.round(R * 0.145))
    S = Math.floor(R * 1.16)
  }
  // Whole canvas pixels per cell, so every cell is the same size.
  k = Math.max(1, Math.min(4, app.frame.scale || 1))
  cell = Math.max(2, Math.floor((S * k) / art.n))
  S = (cell * art.n) / k

  canvas = frameos.canvas('grid', cell * art.n, cell * art.n, T.well)
  if (!canvas) return <div className="flex items-center justify-center w-full h-full bg-white text-black text-2xl">Not enough memory</div>
  const look = [hc, art.n, cell, palette.join(''), showGrid, art.gen].join('|')
  if (canvas.fresh || frameos.recall('look') !== look) {
    paintAll()
    frameos.remember('look', look)
  }

  show()

  const grid = <Grid S={S} src={canvas} />
  const tools = <Tools b={b} cols={toolCols} hcLook={hc} />
  const pal = <Palette sw={sw} cols={palCols} />
  // Only where it is drawn: a status line never drawn would be one no tap can redraw alone.
  const label = () => <Status size={z(14)} hcLook={hc} />
  const sheetW = Math.min(W - 24, z(520))
  if (round) {
    const side = Math.floor(R * Math.SQRT2)
    // Pads along the rim: n of them, `size` across, centred on the angle `at`
    // (0 is the top, clockwise), each `size` and a little apart.
    const along = (items, size, at) => {
      const r = R - size / 2
      const step = (size + 6) / r
      return items.map((item, i) => {
        const a = at + (i - (items.length - 1) / 2) * step
        return (
          <div className={`absolute left-[${Math.round(W / 2 + r * Math.sin(a) - size / 2)}px] top-[${Math.round(H / 2 - r * Math.cos(a) - size / 2)}px]`}>{item}</div>
        )
      })
    }
    const toolList = [
      ...TOOLS.map(([id, label, d]) => <ToolButton b={b} id={id} label={label} d={d} hcLook={hc} />),
      <MirrorButton b={b} hcLook={hc} />,
      <UndoButton b={b} hcLook={hc} />,
      <RedoButton b={b} hcLook={hc} />,
      <FileButton b={b} hcLook={hc} />,
    ]
    const colors = hc
      ? [<Swatch sw={sw} color="#000000" i={0} hcLook={hc} />, <Swatch sw={sw} color="#ffffff" i={1} hcLook={hc} />, <DitherSwatch sw={sw} />]
      : palette.map((color, i) => <Swatch sw={sw} color={color} i={i} hcLook={hc} />)
    const half = Math.ceil(colors.length / 2)
    return (
      <div className={`relative w-[${W}px] h-[${H}px] ${T.page}`}>
        <div className={`absolute left-[${Math.round((W - S) / 2)}px] top-[${Math.round((H - S) / 2)}px]`}>{grid}</div>
        {along(toolList.slice(0, 4), b, 0)}
        {along(toolList.slice(4).reverse(), b, Math.PI)}
        {along(colors.slice(0, half).reverse(), sw, -Math.PI / 2)}
        {along(colors.slice(half), sw, Math.PI / 2)}
        {ui.note && !ui.panel ? (
          <div className={`absolute top-[${Math.round(H / 2 - 20)}px] left-0 right-0 flex justify-center`}>
            <div className={`px-[${z(16)}px] py-[${z(8)}px] rounded-[${z(12)}px] text-[${z(16)}px] max-w-[${side}px] ${T.note}`} onPointerDown={() => {}} onClick={() => setUi({ note: '' })}>{ui.note}</div>
          </div>
        ) : null}
        {ui.panel === 'menu' ? <MenuSheet w={side} gridSetting={gridSetting} /> : null}
        {ui.panel === 'open' ? <OpenSheet w={side} h={side} /> : null}
        {ui.panel === 'save' ? <SaveSheet w={side} /> : null}
      </div>
    )
  }
  return (
    <div className={`w-[${W}px] h-[${H}px] p-[${pad}px] ${T.page}`}>
      {layout === 'wide' ? (
        <div className={`flex gap-[${gap}px]`}>
          {grid}
          <div className={`flex-1 flex flex-col gap-[${gap}px] min-w-0`}>
            {tools}
            {pal}
            {label()}
          </div>
        </div>
      ) : layout === 'tall' ? (
        <div className={`flex flex-col items-center gap-[${gap}px]`}>
          {grid}
          {label()}
          {pal}
          {tools}
        </div>
      ) : (
        <div className={`flex flex-col gap-[${gap}px]`}>
          <div className={`flex gap-[${gap}px]`}>
            {grid}
            {pal}
          </div>
          {tools}
        </div>
      )}
      {ui.note && !ui.panel ? (
        <div className={`absolute bottom-[${z(16)}px] left-0 right-0 flex justify-center`}>
          <div className={`px-[${z(16)}px] py-[${z(8)}px] rounded-[${z(12)}px] text-[${z(16)}px] ${T.note}`} onPointerDown={() => {}} onClick={() => setUi({ note: '' })}>{ui.note}</div>
        </div>
      ) : null}
      {ui.panel === 'menu' ? <MenuSheet w={sheetW} gridSetting={gridSetting} /> : null}
      {ui.panel === 'open' ? <OpenSheet w={sheetW} h={Math.min(H - 24, z(460))} /> : null}
      {ui.panel === 'save' ? <SaveSheet w={sheetW} /> : null}
    </div>
  )
}

// back undoes, forward redoes; Ctrl+Z / Ctrl+Y on a keyboard.
export function onEvent(app, context) {
  if (!art) art = loadArt(app, 16)
  if (!ui) ui = loadUi()
  const key = String(context.payload?.key || '').toLowerCase()
  if (context.event === 'back' || (context.event === 'keyDown' && context.payload?.ctrl && key === 'z')) {
    undo()
    return true
  }
  if (context.event === 'forward' || (context.event === 'keyDown' && context.payload?.ctrl && key === 'y')) {
    redo()
    return true
  }
  return false
}

